CREATE TABLE world_event_schema(version INTEGER PRIMARY KEY);
INSERT INTO world_event_schema VALUES(1);
CREATE TABLE world_events(id TEXT PRIMARY KEY,type TEXT NOT NULL,status TEXT NOT NULL,world TEXT NOT NULL,x INTEGER NOT NULL,y INTEGER NOT NULL,z INTEGER NOT NULL,starts INTEGER NOT NULL,expires INTEGER NOT NULL,stage INTEGER NOT NULL DEFAULT 0,health REAL NOT NULL DEFAULT 0,claimed_by TEXT,cleanup_after INTEGER NOT NULL DEFAULT 0,settings TEXT NOT NULL,escrow INTEGER NOT NULL CHECK(escrow>=0),treasury TEXT NOT NULL,preserve_structure INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX world_event_live ON world_events((1)) WHERE status NOT IN ('FINISHED','CANCELED');
CREATE TABLE world_event_blocks(event TEXT NOT NULL REFERENCES world_events(id),x INTEGER NOT NULL,y INTEGER NOT NULL,z INTEGER NOT NULL,original TEXT NOT NULL,placed TEXT NOT NULL,PRIMARY KEY(event,x,y,z));
CREATE TABLE world_event_chests(event TEXT NOT NULL REFERENCES world_events(id),chest INTEGER NOT NULL,x INTEGER NOT NULL,y INTEGER NOT NULL,z INTEGER NOT NULL,owner TEXT,PRIMARY KEY(event,chest));
CREATE TABLE world_event_damage(event TEXT NOT NULL REFERENCES world_events(id),player TEXT NOT NULL,damage REAL NOT NULL CHECK(damage>=0),PRIMARY KEY(event,player));
CREATE TABLE world_event_entities(event TEXT NOT NULL REFERENCES world_events(id),entity TEXT PRIMARY KEY,role TEXT NOT NULL,wave INTEGER NOT NULL,dead INTEGER NOT NULL DEFAULT 0);
CREATE TABLE world_event_awards(id TEXT PRIMARY KEY,event TEXT NOT NULL REFERENCES world_events(id),owner TEXT NOT NULL,kind TEXT NOT NULL,tier TEXT,receipt TEXT,payload BLOB,amount INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE world_event_settings(name TEXT PRIMARY KEY,value TEXT NOT NULL);
